const b = ($input.first().json.body) || {};
const partes = [];
if (b.filtro_remitente) partes.push('from:' + b.filtro_remitente);
if (b.filtro_asunto) partes.push('subject:' + b.filtro_asunto);
if (b.con_adjuntos === true) partes.push('has:attachment');
if (b.recibido_despues) partes.push('after:' + b.recibido_despues);
return [{ json: {
  q: partes.join(' '),
  limite: Number(b.limite) > 0 ? Number(b.limite) : 10,
  solo_no_leidos: b.solo_no_leidos === true,
  descargar_adjuntos: b.descargar_adjuntos !== false
} }];

const mensajes = [];
for (const item of $input.all()) {
  const j = item.json || {};
  if (!j.id) continue;
  const bin = item.binary || {};
  const adjuntos = Object.keys(bin).map(k => ({
    campo_binario: k,
    nombre: bin[k].fileName || k,
    mime: bin[k].mimeType || '',
    tamano: bin[k].fileSize || null
  }));
  mensajes.push({
    id: j.id,
    hilo: j.threadId || '',
    de: (j.from && j.from.text) || '',
    para: (j.to && j.to.text) || '',
    asunto: j.subject || '',
    fecha: j.date || '',
    adjuntos: adjuntos
  });
}
return [{ json: { ok: true, cantidad: mensajes.length, mensajes: mensajes } }];
